/** App-owned camera screen, with live contour overlay and deliberate fallback choices. */
public class ScanActivity extends ComponentActivity {
    private PreviewView preview;private EdgeOverlay overlay;private TextView guide;private Button flash,autoMode,manualMode,shutter;private ImageCapture capture;private androidx.camera.core.Camera camera;private ProcessCameraProvider provider;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private volatile boolean manual,busy;private boolean torch;private volatile long lastFrame;private boolean binding,ready,processingFrame,samplingPaused;private int session,shot;private File shotFile,systemFile;private final Handler handler=new Handler(Looper.getMainLooper());private Runnable timeout;private final ScanStability stability=new ScanStability();private long focusAt;private final Runnable sampleFrame=new Runnable(){public void run(){if(isFinishing()||isDestroyed())return;if(ready&&!busy&&!processingFrame&&!samplingPaused){Bitmap bitmap=preview.getBitmap();if(bitmap!=null){lastFrame=SystemClock.elapsedRealtime();analyzePreview(bitmap,lastFrame);}}handler.postDelayed(this,220);}};
    @Override public void onCreate(Bundle state){super.onCreate(state);manual=state==null?ScanSettings.manual(this):state.getBoolean("manual");if(state!=null&&!state.getString("systemFile","").isEmpty())systemFile=new File(state.getString("systemFile"));
        LinearLayout page=new LinearLayout(this);page.setOrientation(1);page.setBackgroundColor(Color.rgb(21,25,31));
        LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);
        Button close=control("✕");close.setContentDescription("촬영 취소");close.setOnClickListener(v->finish());top.addView(close,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));
        TextView title=Ui.text(this,"명함 촬영",17,true);title.setTextColor(Color.WHITE);title.setGravity(Gravity.CENTER);top.addView(title,Ui.weight(1));
        flash=control("플래시 끔");flash.setTextSize(11);top.addView(flash);flash.setOnClickListener(v->{if(camera!=null&&camera.getCameraInfo().hasFlashUnit()){torch=!torch;camera.getCameraControl().enableTorch(torch);flash.setText(torch?"플래시 켬":"플래시 끔");flash.setContentDescription(flash.getText());}else toast("이 카메라는 플래시를 지원하지 않습니다.");});
        Button help=control("ⓘ");help.setContentDescription("촬영 도움말");top.addView(help,new LinearLayout.LayoutParams(Ui.dp(this,48),Ui.dp(this,48)));help.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("촬영 도움말").setMessage("명함을 평평하게 두고 빛 반사를 피해 주세요. 화면을 누르면 초점을 맞춥니다. 파란 테두리는 발견한 명함, 초록 테두리는 촬영 준비 상태입니다. 자동 모드에서는 안정되면 촬영하며, 수동 모드에서는 촬영 버튼을 누르세요. 촬영 후 네 모서리를 수정할 수 있습니다.").setItems(new String[]{"카메라 다시 연결","휴대폰 카메라로 촬영","Google 스캐너 사용","촬영 진단 확인"},(d,w)->{if(w==0)startCamera();else if(w==1)systemCamera();else if(w==2)google();else new AlertDialog.Builder(this).setTitle("촬영 진단").setMessage(getSharedPreferences("camera_diagnostics",0).getString("last","기록 없음")).setPositiveButton("닫기",null).show();}).setNegativeButton("닫기",null).show());page.addView(top);
        FrameLayout frame=new FrameLayout(this);preview=new PreviewView(this);preview.setImplementationMode(PreviewView.ImplementationMode.COMPATIBLE);preview.setScaleType(PreviewView.ScaleType.FILL_CENTER);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));overlay=new EdgeOverlay();frame.addView(overlay,new FrameLayout.LayoutParams(-1,-1));
        guide=Ui.text(this,"명함을 화면 중앙에 맞춰주세요",12,false);guide.setTextColor(Color.WHITE);guide.setGravity(Gravity.CENTER);guide.setPadding(Ui.dp(this,12),Ui.dp(this,8),Ui.dp(this,12),Ui.dp(this,8));guide.setBackground(Ui.rounded(0xB321252B,18,this));FrameLayout.LayoutParams hint=new FrameLayout.LayoutParams(-2,-2,Gravity.TOP|Gravity.CENTER_HORIZONTAL);hint.topMargin=Ui.dp(this,12);hint.leftMargin=hint.rightMargin=Ui.dp(this,12);frame.addView(guide,hint);page.addView(frame,new LinearLayout.LayoutParams(-1,0,1));
        preview.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_UP&&camera!=null){MeteringPoint point=preview.getMeteringPointFactory().createPoint(e.getX(),e.getY());camera.getCameraControl().startFocusAndMetering(new FocusMeteringAction.Builder(point,FocusMeteringAction.FLAG_AF|FocusMeteringAction.FLAG_AE).setAutoCancelDuration(3,TimeUnit.SECONDS).build());v.performClick();}return true;});
        LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,Ui.dp(this,8),0,0);
        Button gallery=new Button(this){private final Paint icon=new Paint(Paint.ANTI_ALIAS_FLAG);@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float x=getWidth()/2f,y=getHeight()/2f,d=Ui.dp(getContext(),11);icon.setColor(Color.WHITE);icon.setStyle(Paint.Style.STROKE);icon.setStrokeWidth(Ui.dp(getContext(),2));canvas.drawRoundRect(x-d,y-d,x+d,y+d,3,3,icon);Path mountain=new Path();mountain.moveTo(x-d+3,y+d-3);mountain.lineTo(x-2,y-1);mountain.lineTo(x+3,y+3);mountain.lineTo(x+6,y-2);mountain.lineTo(x+d-3,y+d-3);canvas.drawPath(mountain,icon);canvas.drawCircle(x+5,y-5,2,icon);}};gallery.setBackgroundColor(Color.TRANSPARENT);gallery.setElevation(0);gallery.setStateListAnimator(null);gallery.setContentDescription("사진 선택");row.addView(gallery,new LinearLayout.LayoutParams(0,Ui.dp(this,72),1));gallery.setOnClickListener(v->pick());
        shutter=new Button(this){private final Paint ring=new Paint(Paint.ANTI_ALIAS_FLAG);@Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(cx,cy)-Ui.dp(getContext(),5);ring.setColor(isEnabled()?Color.WHITE:Color.LTGRAY);ring.setStyle(Paint.Style.STROKE);ring.setStrokeWidth(Ui.dp(getContext(),3));canvas.drawCircle(cx,cy,r,ring);ring.setStyle(Paint.Style.FILL);canvas.drawCircle(cx,cy,r-Ui.dp(getContext(),8),ring);}};shutter.setEnabled(false);shutter.setText("");shutter.setBackgroundColor(Color.TRANSPARENT);shutter.setElevation(0);shutter.setStateListAnimator(null);shutter.setContentDescription("명함 촬영 버튼");row.addView(shutter,new LinearLayout.LayoutParams(Ui.dp(this,80),Ui.dp(this,80)));shutter.setOnClickListener(v->take());View balance=new View(this);row.addView(balance,new LinearLayout.LayoutParams(0,Ui.dp(this,72),1));page.addView(row);
        LinearLayout choices=new LinearLayout(this);choices.setGravity(Gravity.CENTER);autoMode=control("자동");manualMode=control("수동");choices.addView(autoMode,new LinearLayout.LayoutParams(Ui.dp(this,96),Ui.dp(this,48)));choices.addView(manualMode,new LinearLayout.LayoutParams(Ui.dp(this,96),Ui.dp(this,48)));autoMode.setOnClickListener(v->selectMode(false));manualMode.setOnClickListener(v->selectMode(true));page.addView(choices);page.setPadding(0,0,0,Ui.dp(this,12));updateMode();Ui.setContentView(this,page,true);
        if(checkSelfPermission(Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)preview.post(this::startCamera);else requestPermissions(new String[]{Manifest.permission.CAMERA},1);
    }
    private Button control(String text){Button b=Ui.button(this,text);b.setTextColor(Color.WHITE);b.setBackgroundColor(Color.TRANSPARENT);return b;}
    private void selectMode(boolean value){manual=value;stability.reset();ScanSettings.setManual(this,manual);updateMode();}
    private void updateMode(){Button[] buttons={autoMode,manualMode};for(int i=0;i<2;i++){boolean selected=i==(manual?1:0);buttons[i].setSelected(selected);buttons[i].setTextColor(selected?Color.WHITE:Color.LTGRAY);buttons[i].setBackground(Ui.rounded(selected?Color.rgb(25,118,210):Color.rgb(46,50,57),24,this));buttons[i].setContentDescription((i==0?"자동 촬영":"수동 촬영")+(selected?" 선택됨":""));}}
    private void diagnostic(String text,Throwable e){String message=android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL+" / Android "+android.os.Build.VERSION.RELEASE+" / v"+BuildConfig.VERSION_NAME+"\n"+text+(e==null?"":"\n"+e.getClass().getSimpleName()+": "+e.getMessage());getSharedPreferences("camera_diagnostics",0).edit().putString("last",message).apply();if(e!=null)android.util.Log.e("LSICamera",text,e);}
    private void startCamera(){if(isFinishing()||isDestroyed()||binding||busy)return;if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)return;if(preview.getWidth()==0||preview.getDisplay()==null){preview.postDelayed(this::startCamera,150);return;}binding=true;ready=false;shutter.setEnabled(false);camera=null;capture=null;lastFrame=0;stability.reset();focusAt=0;final int generation=++session;guide.setText("카메라 준비 중…");
        com.google.common.util.concurrent.ListenableFuture<ProcessCameraProvider> future=ProcessCameraProvider.getInstance(this);future.addListener(()->{if(isFinishing()||isDestroyed()||generation!=session)return;try{provider=future.get();bindCamera(generation);}catch(Exception e){binding=false;cameraFailure(e);}},ContextCompat.getMainExecutor(this));
        handler.postDelayed(()->{if(generation==session&&!ready&&!isFinishing()&&!isDestroyed()){binding=false;cameraFailure(new IOException("카메라 준비 시간 초과"));}},12000);
    }
    private void bindCamera(int generation)throws Exception{
        provider.unbindAll();int rotation=preview.getDisplay().getRotation();Preview use=new Preview.Builder().setTargetAspectRatio(AspectRatio.RATIO_4_3).setTargetRotation(rotation).build();
        ImageCapture candidate=new ImageCapture.Builder().setTargetAspectRatio(AspectRatio.RATIO_4_3).setCaptureMode(ImageCapture.CAPTURE_MODE_MINIMIZE_LATENCY).setFlashMode(ImageCapture.FLASH_MODE_OFF).setTargetRotation(rotation).build();use.setSurfaceProvider(preview.getSurfaceProvider());
        UseCaseGroup.Builder group=new UseCaseGroup.Builder().addUseCase(use).addUseCase(candidate);ViewPort viewport=preview.getViewPort();if(viewport!=null)group.setViewPort(viewport);camera=provider.bindToLifecycle(this,CameraSelector.DEFAULT_BACK_CAMERA,group.build());capture=candidate;binding=false;
        camera.getCameraInfo().getCameraState().observe(this,state->{if(generation!=session||isFinishing()||isDestroyed())return;if(state.getError()!=null){diagnostic("카메라 상태 오류 "+state.getError().getCode(),state.getError().getCause());guide.setText("카메라 연결을 확인하세요 · 도움말에서 재연결");}if(state.getType()==CameraState.Type.OPEN){ready=true;shutter.setEnabled(!busy);guide.setText("명함을 화면 중앙에 맞춰주세요");handler.removeCallbacks(sampleFrame);handler.post(sampleFrame);diagnostic("미리보기 기반 외곽선 분석 연결 완료",null);}});flash.setEnabled(camera.getCameraInfo().hasFlashUnit());
    }
    private void cameraFailure(Exception e){ready=false;shutter.setEnabled(false);guide.setText("카메라 연결 실패 · 도움말에서 재연결 또는 휴대폰 카메라");diagnostic("카메라 연결 실패",e);toast("카메라를 연결하지 못했습니다. 오른쪽 위 도움말에서 다시 연결하세요.");}
    // Bitmap is exactly the displayed PreviewView content: crop, rotation and scaling are
    // already applied by CameraX. No sensor/cropRect coordinates are guessed here.
    void analyzePreview(Bitmap input,long now){if(processingFrame||isFinishing()||isDestroyed()){input.recycle();return;}processingFrame=true;final int generation=session;worker.execute(()->{Bitmap bitmap=input;try{if(Math.max(input.getWidth(),input.getHeight())>960){float scale=960f/Math.max(input.getWidth(),input.getHeight());bitmap=Bitmap.createScaledBitmap(input,Math.max(1,Math.round(input.getWidth()*scale)),Math.max(1,Math.round(input.getHeight()*scale)),true);}CardEdges.Detection result=CardEdges.detect(bitmap);final int width=bitmap.getWidth(),height=bitmap.getHeight();runOnUiThread(()->{processingFrame=false;if(generation==session)acceptDetection(result,width,height,0,now);});}catch(Exception e){diagnostic("미리보기 외곽선 분석 실패",e);runOnUiThread(()->{processingFrame=false;if(generation==session&&!busy)guide.setText("외곽선 분석을 다시 시도합니다 · 수동 촬영 가능");});}finally{if(bitmap!=input)bitmap.recycle();input.recycle();}});}
    void acceptDetection(CardEdges.Detection result,int width,int height,float unused,long now){if(isFinishing()||isDestroyed()||busy||!ready)return;boolean fire=stability.update(result,now);float[] corners=stability.corners();boolean found=result.corners!=null;overlay.set(corners,width,height,fire);if(!found){guide.setText("명함 네 모서리가 보이도록 맞춰주세요");return;}if(result.sharpness<ScanStability.MIN_SHARPNESS){guide.setText("명함에 초점을 맞추는 중…");}else guide.setText(manual?"테두리를 확인하고 촬영 버튼을 누르세요":fire?"자동 촬영합니다":"명함을 찾았습니다 · 잠시 움직이지 마세요");
        if(now-focusAt>3500&&camera!=null){focusAt=now;float x=0,y=0;for(int i=0;i<4;i++){x+=corners[2*i]/4;y+=corners[2*i+1]/4;}try{MeteringPoint point=preview.getMeteringPointFactory().createPoint(x*preview.getWidth(),y*preview.getHeight());camera.getCameraControl().startFocusAndMetering(new FocusMeteringAction.Builder(point,FocusMeteringAction.FLAG_AF|FocusMeteringAction.FLAG_AE).setAutoCancelDuration(3,TimeUnit.SECONDS).build());}catch(Exception e){diagnostic("명함 자동 초점",e);}}
        if(fire&&!manual)take();}
    void take(){if(busy)return;if(!ready||capture==null){toast("카메라 준비 중입니다. 잠시 후 촬영하세요.");return;}busy=true;shutter.setEnabled(false);autoMode.setEnabled(false);manualMode.setEnabled(false);stability.reset();guide.setText("촬영 중…");final int token=++shot;try{File file=CardFileProvider.newCameraFile(this,"native");shotFile=file;timeout=()->{if(busy&&token==shot&&!isFinishing()&&!isDestroyed()){++shot;if(provider!=null)provider.unbindAll();failed(new IOException("촬영 응답 시간 초과"));startCamera();}};handler.postDelayed(timeout,12000);capture.takePicture(new ImageCapture.OutputFileOptions.Builder(file).build(),ContextCompat.getMainExecutor(this),new ImageCapture.OnImageSavedCallback(){public void onImageSaved(ImageCapture.OutputFileResults result){if(token!=shot||isFinishing()||isDestroyed()){file.delete();return;}handler.removeCallbacks(timeout);try{String path=ImageUtil.copyFileToCards(ScanActivity.this,file,"capture");file.delete();shotFile=null;diagnostic("촬영 JPEG 저장 완료",null);setResult(RESULT_OK,new Intent().putExtra("path",path));finish();}catch(Exception e){file.delete();failed(e);}}public void onError(ImageCaptureException e){file.delete();if(token==shot){handler.removeCallbacks(timeout);failed(e);}}});}catch(Exception e){if(timeout!=null)handler.removeCallbacks(timeout);failed(e);}}
    private void failed(Exception e){busy=false;shutter.setEnabled(ready);autoMode.setEnabled(true);manualMode.setEnabled(true);stability.reset();guide.setText("촬영 실패 · 다시 촬영하거나 도움말을 확인하세요");diagnostic("촬영 실패",e);toast("촬영하지 못했습니다. 재시도하거나 도움말에서 휴대폰 카메라를 선택하세요.");}
    private void systemCamera(){try{systemFile=CardFileProvider.newCameraFile(this,"system");android.net.Uri uri=CardFileProvider.uriFor(this,systemFile);Intent i=new Intent(android.provider.MediaStore.ACTION_IMAGE_CAPTURE).putExtra(android.provider.MediaStore.EXTRA_OUTPUT,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);i.setClipData(ClipData.newRawUri("명함 촬영",uri));if(i.resolveActivity(getPackageManager())==null){toast("휴대폰 카메라 앱을 찾을 수 없습니다.");return;}if(provider!=null)provider.unbindAll();ready=false;startActivityForResult(i,4);}catch(Exception e){failed(e);}}
    private void pick(){startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("image/*").addCategory(Intent.CATEGORY_OPENABLE),2);}
    private void google(){busy=true;if(provider!=null)provider.unbindAll();DocumentScan.launch(this,3,()->true,error->{busy=false;startCamera();toast("Google 스캐너를 열 수 없습니다. 직접 촬영 또는 사진 선택을 사용하세요.");});}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(result!=RESULT_OK){busy=false;if(systemFile!=null){systemFile.delete();systemFile=null;}startCamera();return;}try{android.net.Uri uri=req==3?DocumentScan.image(data):data==null?null:data.getData();if(req==4){if(systemFile==null||systemFile.length()==0)throw new IOException("휴대폰 카메라의 사진이 없습니다.");String path=ImageUtil.copyFileToCards(this,systemFile,"capture");systemFile.delete();systemFile=null;setResult(RESULT_OK,new Intent().putExtra("path",path));finish();return;}if(uri==null)throw new IOException("선택한 사진이 없습니다.");String path=ImageUtil.copyUriToCards(this,uri,"scan_import");setResult(RESULT_OK,new Intent().putExtra("path",path));finish();}catch(Exception e){failed(e);}}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==1&&grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)startCamera();else if(request==1){guide.setText("카메라 권한이 필요합니다. 사진 선택은 사용할 수 있습니다.");shutter.setEnabled(false);}}
    @Override protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putBoolean("manual",manual);state.putString("systemFile",systemFile==null?"":systemFile.getAbsolutePath());}
    @Override protected void onDestroy(){++session;++shot;handler.removeCallbacksAndMessages(null);if(provider!=null)provider.unbindAll();worker.shutdown();if(shotFile!=null)shotFile.delete();super.onDestroy();}
    boolean cameraReady(){return ready&&capture!=null&&camera!=null&&lastFrame>0;}
    private void toast(String s){Toast.makeText(this,s==null?"촬영 오류":s,Toast.LENGTH_LONG).show();}
    private final class EdgeOverlay extends View {
        private final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);private float[] q;private int iw=1,ih=1;private boolean ready;
        EdgeOverlay(){super(ScanActivity.this);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
        void set(float[] corners,int w,int h,boolean stable){q=corners;iw=w;ih=h;ready=stable;invalidate();}
        protected void onDraw(Canvas canvas){paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(Ui.dp(getContext(),2));
            if(q==null){paint.setColor(0x66FFFFFF);float width=getWidth()*.8f,height=Math.min(getHeight()*.6f,width/1.58f),cx=getWidth()/2f,cy=getHeight()/2f,length=Ui.dp(getContext(),16);for(int xSign:new int[]{-1,1})for(int ySign:new int[]{-1,1}){float x=cx+xSign*width/2,y=cy+ySign*height/2;canvas.drawLine(x,y,x-xSign*length,y,paint);canvas.drawLine(x,y,x,y-ySign*length,paint);}return;}
            Path path=new Path();for(int i=0;i<4;i++){float x=q[i*2]*getWidth(),y=q[i*2+1]*getHeight();if(i==0)path.moveTo(x,y);else path.lineTo(x,y);}path.close();paint.setColor(ready?Color.rgb(72,215,133):Color.rgb(64,180,245));canvas.drawPath(path,paint);
        }
    }
}
